/* ── Unit 04 Problem Bank — Electron Configuration
   171 problems total (81 original + 60 added + 30 hard expansion)
   Difficulty: 62 easy | 58 medium | 51 hard
   Served via netlify/functions/get-premium-problem-set.js
   NOT imported by any public-facing page.
─────────────────────────────────────────────────────── */

export const ALL_PROBLEMS = [

  // ─── CALCULATION (30 problems) ────────────────────────────────

  {id:'p01', difficulty:'easy', type:'calc', tag:'Wave Equations', q:'What is the frequency (in Hz) of light with a wavelength of 600.0 nm?', answer:5.00e14, unit:'Hz', tolerance:1e13, solution:'<p>ν = c/λ = (3.00×10^8 m/s) ÷ (600.0×10^-9 m) = <strong>5.00 × 10^14 Hz</strong></p>'},
  {id:'p02', difficulty:'easy', type:'calc', tag:'Wave Equations', q:'What is the wavelength (in nm) of light with a frequency of 7.50 × 10^14 Hz?', answer:400.0, unit:'nm', tolerance:2, solution:'<p>λ = c/ν = (3.00×10^8) ÷ (7.50×10^14) = 4.00×10^-7 m = <strong>400.0 nm</strong></p>'},
  {id:'p03', difficulty:'easy', type:'calc', tag:'Photon Energy', q:'What is the energy (in J) of a single photon of green light with a frequency of 5.45 × 10^14 Hz?', answer:3.61e-19, unit:'J', tolerance:5e-21, solution:'<p>E = hν = (6.626×10^-34) × (5.45×10^14) = <strong>3.61 × 10^-19 J</strong></p>'},
  {id:'p04', difficulty:'medium', type:'calc', tag:'Photon Energy', q:'What is the energy (in J) of a photon of ultraviolet light with λ = 250 nm?', answer:7.95e-19, unit:'J', tolerance:1e-20, solution:'<p>First convert wavelength to frequency with ν = c/λ.</p><p>ν = (3.00×10^8) ÷ (250×10^-9) = 1.20×10^15 Hz</p><p>Then use E = hν.</p><p>E = (6.626×10^-34)(1.20×10^15) = <strong>7.95 × 10^-19 J</strong></p>'},
  {id:'p05', difficulty:'easy', type:'calc', tag:'Wave Equations', q:'The Hβ Balmer line of hydrogen has a wavelength of 486.1 nm. What is its frequency in Hz?', answer:6.17e14, unit:'Hz', tolerance:5e12, solution:'<p>ν = c/λ = (3.00×10^8)÷(486.1×10^-9) = <strong>6.17 × 10^14 Hz</strong></p>'},
  {id:'p06', difficulty:'easy', type:'calc', tag:'Photon Energy', q:'Infrared radiation has a wavelength of 1000 nm. What is the energy of one photon in joules?', answer:1.99e-19, unit:'J', tolerance:5e-21, solution:'<p>ν = (3.00×10^8)÷(1000×10^-9) = 3.00×10^14 Hz<br>E = (6.626×10^-34)(3.00×10^14) = <strong>1.99 × 10^-19 J</strong></p>'},
  {id:'p07', difficulty:'medium', type:'calc', tag:'Photon Energy', q:'What is the wavelength in nm of a photon that has an energy of 4.09 × 10^-19 J?', answer:486.0, unit:'nm', tolerance:3, solution:'<p>ν = E/h = (4.09×10^-19)÷(6.626×10^-34) = 6.172×10^14 Hz<br>λ = c/ν = (3.00×10^8)÷(6.172×10^14) = 4.86×10^-7 m = <strong>486 nm</strong></p>'},
  {id:'p08', difficulty:'easy', type:'calc', tag:'Bohr Model', q:'Calculate the energy (in J) of the hydrogen electron at the n = 2 level. Use Eₙ = -2.18 × 10^-18 / n^2.', answer:-5.45e-19, unit:'J', tolerance:1e-20, solution:'<p>E2 = -2.18×10^-18 ÷ (2^2) = -2.18×10^-18 ÷ 4 = <strong>-5.45 × 10^-19 J</strong></p>'},
  {id:'p09', difficulty:'easy', type:'calc', tag:'Bohr Model', q:'Calculate the energy (in J) of the hydrogen electron at the n = 3 level. Use Eₙ = -2.18 × 10^-18 / n^2.', answer:-2.42e-19, unit:'J', tolerance:5e-21, solution:'<p>E3 = -2.18×10^-18 ÷ (3^2) = -2.18×10^-18 ÷ 9 = <strong>-2.42 × 10^-19 J</strong></p>'},
  {id:'p10', difficulty:'medium', type:'calc', tag:'Bohr Model', q:'What is the energy of the photon emitted when a hydrogen electron falls from n = 3 to n = 2? Give your answer as a positive number (energy of the emitted photon).', answer:3.03e-19, unit:'J', tolerance:5e-21, solution:'<p>Write the two energy levels first: E3 = -2.42×10^-19 J and E2 = -5.45×10^-19 J.</p><p>Now subtract to find the change in electron energy.</p><p>ΔE = E2 - E3 = -5.45×10^-19 - (-2.42×10^-19) = -3.03×10^-19 J</p><p>The negative sign means energy was emitted, so the photon\'s energy is the magnitude: <strong>3.03 × 10^-19 J</strong>.</p>'},
  {id:'p11', difficulty:'medium', type:'calc', tag:'Bohr Model', q:'What wavelength (nm) corresponds to a photon of energy 3.03 × 10^-19 J? (This is the Hα red Balmer line.)', answer:656.0, unit:'nm', tolerance:5, solution:'<p>ν = E/h = (3.03×10^-19)÷(6.626×10^-34) = 4.573×10^14 Hz<br>λ = c/ν = (3.00×10^8)÷(4.573×10^14) = 6.56×10^-7 m = <strong>656 nm</strong></p>'},
  {id:'p12', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'How many orbitals are in the n = 3 energy level?', answer:9, unit:'orbitals', tolerance:0, solution:'<p>n=3 has: 3s (1) + 3p (3) + 3d (5) = <strong>9 orbitals</strong></p>'},
  {id:'p13', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the n = 4 energy level?', answer:32, unit:'electrons', tolerance:0, solution:'<p>n=4: 4s(2) + 4p(6) + 4d(10) + 4f(14) = <strong>32 electrons</strong></p>'},
  {id:'p14', difficulty:'medium', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does sulfur (Z = 16) have in its ground state?', answer:2, unit:'unpaired electrons', tolerance:0, solution:'<p>Start with the electron configuration: S = [Ne] 3s^2 3p^4.</p><p>Place the 4 p electrons using Hund\'s rule: one electron goes into each p orbital before pairing.</p><p>That gives 3p as ↑↓ ↑ ↑, so sulfur has <strong>2 unpaired electrons</strong>.</p>'},
  {id:'p15', difficulty:'easy', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does nitrogen (Z = 7) have in its ground state?', answer:3, unit:'unpaired electrons', tolerance:0, solution:'<p>N: 1s^2 2s^2 2p^3<br>2p diagram: ↑ ↑ ↑ (Hund\'s rule) → <strong>3 unpaired electrons</strong></p>'},
  {id:'p16', difficulty:'medium', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does iron (Z = 26) have in its ground state?', answer:4, unit:'unpaired electrons', tolerance:0, solution:'<p>Fe: [Ar] 4s^2 3d^6<br>3d: ↑↓ ↑ ↑ ↑ ↑ → <strong>4 unpaired electrons</strong></p>'},
  {id:'p17', difficulty:'medium', type:'calc', tag:'Exceptions', q:'How many total electrons are in the 3d sublevel of chromium (Z = 24) in its actual ground state?', answer:5, unit:'electrons', tolerance:0, solution:'<p>Chromium is one of the common electron-configuration exceptions.</p><p>Instead of [Ar] 4s^2 3d^4, its actual ground state is [Ar] 4s^1 3d^5 because a half-filled d sublevel is more stable.</p><p>So the 3d sublevel contains <strong>5 electrons</strong>.</p>'},
  {id:'p18', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the 2p sublevel?', answer:6, unit:'electrons', tolerance:0, solution:'<p>The 2p sublevel has 3 orbitals × 2 electrons each = <strong>6 electrons maximum</strong></p>'},
  {id:'p19', difficulty:'easy', type:'calc', tag:'Wave Equations', q:'What is the frequency (in Hz) of orange light with a wavelength of 620 nm?', answer:4.84e14, unit:'Hz', tolerance:5e12, solution:'<p>ν = c/λ = (3.00×10^8)÷(620×10^-9) = <strong>4.84 × 10^14 Hz</strong></p>'},
  {id:'p20', difficulty:'easy', type:'calc', tag:'Wave Equations', q:'What is the wavelength (in nm) of a photon with frequency 3.00 × 10^15 Hz?', answer:100.0, unit:'nm', tolerance:2, solution:'<p>λ = c/ν = (3.00×10^8)÷(3.00×10^15) = 1.00×10^-7 m = <strong>100 nm</strong> (UV range)</p>'},
  {id:'p21', difficulty:'easy', type:'calc', tag:'Bohr Model', q:'Calculate the energy (in J) of the hydrogen electron at n = 1. Use Eₙ = -2.18 × 10^-18 / n^2.', answer:-2.18e-18, unit:'J', tolerance:5e-20, solution:'<p>E1 = -2.18×10^-18 ÷ (1^2) = <strong>-2.18 × 10^-18 J</strong> — this is the ground state, the lowest possible energy.</p>'},
  {id:'p22', difficulty:'easy', type:'calc', tag:'Bohr Model', q:'Calculate the energy (in J) of the hydrogen electron at n = 4. Use Eₙ = -2.18 × 10^-18 / n^2.', answer:-1.36e-19, unit:'J', tolerance:3e-21, solution:'<p>E4 = -2.18×10^-18 ÷ (4^2) = -2.18×10^-18 ÷ 16 = <strong>-1.36 × 10^-19 J</strong></p>'},
  {id:'p23', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'How many orbitals are in the n = 2 energy level?', answer:4, unit:'orbitals', tolerance:0, solution:'<p>n=2 has: 2s (1 orbital) + 2p (3 orbitals) = <strong>4 orbitals</strong></p>'},
  {id:'p24', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the n = 2 energy level?', answer:8, unit:'electrons', tolerance:0, solution:'<p>n=2: 2s(2) + 2p(6) = <strong>8 electrons</strong></p>'},
  {id:'p25', difficulty:'easy', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does oxygen (Z = 8) have in its ground state?', answer:2, unit:'unpaired electrons', tolerance:0, solution:'<p>O: [He] 2s^2 2p^4<br>2p orbital diagram: ↑↓ | ↑ | ↑ → <strong>2 unpaired electrons</strong></p>'},
  {id:'p26', difficulty:'medium', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does manganese (Z = 25) have in its ground state?', answer:5, unit:'unpaired electrons', tolerance:0, solution:'<p>Mn: [Ar] 4s^2 3d^5<br>3d diagram: ↑ | ↑ | ↑ | ↑ | ↑ (Hund\'s rule — all 5 singly filled) → <strong>5 unpaired electrons</strong></p>'},
  {id:'p27', difficulty:'medium', type:'calc', tag:'Exceptions', q:'How many total electrons are in the 3d sublevel of copper (Z = 29) in its actual ground state?', answer:10, unit:'electrons', tolerance:0, solution:'<p>Cu exception: [Ar] 4s^1 3d^10 (fully-filled d is extra stable) → <strong>10 electrons in 3d</strong></p>'},
  {id:'p28', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the 3d sublevel?', answer:10, unit:'electrons', tolerance:0, solution:'<p>The 3d sublevel has 5 orbitals × 2 electrons each = <strong>10 electrons maximum</strong></p>'},
  {id:'p29', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'How many orbitals are in the 2p sublevel?', answer:3, unit:'orbitals', tolerance:0, solution:'<p>Every p sublevel contains <strong>3 orbitals</strong>. In the case of 2p, those three orbitals together hold up to 6 electrons.</p>'},
  {id:'p30', difficulty:'easy', type:'calc', tag:'Photon Energy', q:'What is the energy (in J) of a photon of red light with λ = 700 nm?', answer:2.84e-19, unit:'J', tolerance:5e-21, solution:'<p>ν = (3.00×10^8)÷(700×10^-9) = 4.286×10^14 Hz<br>E = hν = (6.626×10^-34)(4.286×10^14) = <strong>2.84 × 10^-19 J</strong></p>'},

  // ─── CONCEPTUAL (33 problems) ─────────────────────────────────

  {id:'p31', difficulty:'easy', type:'concept', tag:'Wave Equations', q:'As wavelength increases, frequency:', choices:['increases','decreases','stays the same','first increases then decreases'], correct:1, solution:'<p>c = λν is rearranged to ν = c/λ. As λ increases, ν decreases — they are inversely proportional.</p>'},
  {id:'p32', difficulty:'easy', type:'concept', tag:'EM Spectrum', q:'Which type of electromagnetic radiation has the highest energy per photon?', choices:['Radio waves','Infrared light','Visible light','Ultraviolet light'], correct:3, solution:'<p>E = hν = hc/λ. UV has the shortest wavelength and highest frequency of these four options, giving it the most energy.</p>'},
  {id:'p33', difficulty:'easy', type:'concept', tag:'Bohr Model', q:'Bohr\'s model of the hydrogen atom explained which observation?', choices:['Why atoms have mass','The continuous blackbody spectrum','The line emission spectrum of hydrogen','The photoelectric effect'], correct:2, solution:'<p>Bohr\'s model explained why hydrogen produces a series of discrete, specific wavelengths (line spectrum) rather than a continuous rainbow.</p>'},
  {id:'p34', difficulty:'easy', type:'concept', tag:'Bohr Model', q:'When an electron in hydrogen absorbs a photon and moves from n = 1 to n = 3, what happens to the electron\'s energy?', choices:['Energy decreases — the transition releases energy','Energy increases — the electron absorbs energy','Energy stays the same','Energy is converted to mass'], correct:1, solution:'<p>Moving from a lower (n=1) to a higher (n=3) level always requires energy INPUT — the electron absorbs a photon.</p>'},
  {id:'p35', difficulty:'easy', type:'concept', tag:'Orbital Shapes', q:'Which of the following correctly describes an s orbital?', choices:['Dumbbell-shaped, holds 6 electrons','Spherical, holds 2 electrons','Clover-shaped, holds 10 electrons','Spherical, holds up to 6 electrons'], correct:1, solution:'<p>An s sublevel has 1 orbital that is spherical in shape and holds a maximum of 2 electrons.</p>'},
  {id:'p36', difficulty:'easy', type:'concept', tag:'Quantum Rules', q:'Which statement correctly describes the Pauli Exclusion Principle?', choices:['Electrons fill the lowest energy orbital first','Electrons spread into separate orbitals before pairing','Each orbital holds at most 2 electrons, and they must have opposite spins','All orbitals in a sublevel fill equally'], correct:2, solution:'<p>Pauli\'s rule in practice: each orbital holds a maximum of 2 electrons, and those two electrons must have opposite spins (↑↓).</p>'},
  {id:'p37', difficulty:'easy', type:'concept', tag:'Quantum Rules', q:'Hund\'s Rule states that:', choices:['Electrons fill lowest energy orbitals first','No two electrons can share an orbital','Within a sublevel, each orbital gets one electron before any orbital gets a second','Electrons must have opposite spins'], correct:2, solution:'<p>Hund\'s rule applies when filling p, d, or f sublevels: fill each orbital singly (all ↑) before doubling up (↑↓).</p>'},
  {id:'p38', difficulty:'medium', type:'concept', tag:'Aufbau', q:'Which sublevel fills immediately before 3d in the Aufbau filling order?', choices:['3p','4s','3s','4p'], correct:1, solution:'<p>Aufbau filling order: … → 3p → 4s → 3d → 4p. The 4s sublevel fills before 3d because 4s has lower energy.</p>'},
  {id:'p39', difficulty:'easy', type:'concept', tag:'Noble Gas Notation', q:'The noble-gas core [Ar] accounts for how many electrons?', choices:['2','11','18','36'], correct:2, solution:'<p>Argon (Z=18) has 18 electrons. Using [Ar] shorthand replaces all 18 inner electrons.</p>'},
  {id:'p40', difficulty:'medium', type:'concept', tag:'Periodic Blocks', q:'Which element is in the d-block of the periodic table?', choices:['Carbon (Z=6)','Calcium (Z=20)','Iron (Z=26)','Iodine (Z=53)'], correct:2, solution:'<p>Iron (Z=26) is in period 4, groups 3-12 (d-block = transition metals). Carbon and Iodine are p-block; Calcium is s-block.</p>'},
  {id:'p41', difficulty:'medium', type:'concept', tag:'Exceptions', q:'Why does chromium (Z=24) have the configuration [Ar] 4s^1 3d^5 instead of [Ar] 4s^2 3d^4?', choices:['4s has higher energy than 3d for this element','A half-filled d sublevel gives extra stability','This is a measurement error','4s only holds 1 electron after the 3rd period'], correct:1, solution:'<p>A half-filled d sublevel (all 5 orbitals with 1 electron each) is especially stable due to symmetry and minimized electron repulsion.</p>'},
  {id:'p42', difficulty:'easy', type:'concept', tag:'Quantum Numbers', q:'An electron is in the 4p sublevel. Which principal energy level (n) does it belong to?', choices:['n = 3','n = 4','n = 5','n = 2'], correct:1, solution:'<p>The number before the letter names the principal energy level. 4p means n = 4.</p>'},
  {id:'p43', difficulty:'easy', type:'concept', tag:'EM Spectrum', q:'Visible light occupies which range of wavelengths?', choices:['10–100 nm','100–400 nm','400–700 nm','700–2500 nm'], correct:2, solution:'<p>The visible spectrum runs from approximately 400 nm (violet) to 700 nm (red). Below 400 nm is UV; above 700 nm is IR.</p>'},
  {id:'p44', difficulty:'medium', type:'concept', tag:'Emission Series', q:'Which hydrogen emission series produces visible light?', choices:['Lyman (n_final = 1)','Balmer (n_final = 2)','Paschen (n_final = 3)','All three produce visible light'], correct:1, solution:'<p>The Balmer series ends at n=2. Transitions from n=3,4,5,6 → n=2 produce the four visible hydrogen lines. Lyman is UV; Paschen is IR.</p>'},
  {id:'p45', difficulty:'easy', type:'concept', tag:'Orbital Counting', q:'How many orbitals are in a d sublevel?', choices:['1','3','5','7'], correct:2, solution:'<p>Every d sublevel contains 5 orbitals, each holding up to 2 electrons, for a maximum of 10 electrons total.</p>'},
  {id:'p46', difficulty:'medium', type:'concept', tag:'Electron Configuration', q:'Which element has the electron configuration [Ne] 3s^2 3p^5?', choices:['Oxygen (Z=8)','Chlorine (Z=17)','Sulfur (Z=16)','Argon (Z=18)'], correct:1, solution:'<p>[Ne]=10e, 3s^2=2e, 3p^5=5e → 10+2+5 = 17 electrons = Chlorine (Z=17).</p>'},
  {id:'p47', difficulty:'easy', type:'concept', tag:'Emission Spectra', q:'An emission spectrum (as opposed to an absorption spectrum) shows:', choices:['Dark lines on a rainbow background','Bright colored lines on a black background','A continuous rainbow','Broad bands of color'], correct:1, solution:'<p>Emission spectra are produced by hot gases releasing energy as photons — bright colored lines appear against a dark background at specific wavelengths.</p>'},
  {id:'p48', difficulty:'medium', type:'concept', tag:'Bohr Model', q:'Which transition in hydrogen produces a photon with the highest energy?', choices:['n=3 → n=2','n=4 → n=3','n=2 → n=1','n=5 → n=4'], correct:2, solution:'<p>The largest energy drop is to n=1 (Lyman series). The n=2 → n=1 transition releases the most energy of these options because n=1 is the lowest level.</p>'},
  {id:'p49', difficulty:'easy', type:'concept', tag:'Quantum Rules', q:'Which of the following correctly states the Pauli Exclusion Principle?', choices:['Electrons spread into separate orbitals before pairing up','Electrons fill the lowest energy sublevel first','Each orbital holds at most 2 electrons, which must have opposite spins','All sublevels in an energy level fill at the same rate'], correct:2, solution:'<p>The Pauli Exclusion Principle means that each orbital can hold a maximum of 2 electrons, and those two must spin in opposite directions (↑↓). You cannot put two spin-up electrons in the same orbital.</p>'},
  {id:'p50', difficulty:'easy', type:'concept', tag:'Orbital Counting', q:'Which energy level is the first to contain a d sublevel?', choices:['n = 1','n = 2','n = 3','n = 4'], correct:2, solution:'<p>The d sublevel first appears at n = 3 (the 3d sublevel). The n=1 level has only s; n=2 has s and p; n=3 adds d.</p>'},
  {id:'p51', difficulty:'easy', type:'concept', tag:'Quantum Rules', q:'Two electrons in the same orbital must have opposite spins. This is a consequence of:', choices:['Hund\'s Rule','Aufbau Principle','Pauli Exclusion Principle','Bohr\'s Model'], correct:2, solution:'<p>The Pauli Exclusion Principle: each orbital holds at most 2 electrons, and they must have opposite spins (↑↓). Two spin-up electrons cannot share the same orbital.</p>'},
  {id:'p52', difficulty:'medium', type:'concept', tag:'Quantum Rules', q:'Which of the following electron configurations violates Hund\'s Rule?', choices:['2p: ↑ | ↑ | ↑','2p: ↑↓ | ↑ | —','2p: ↑ | ↑ | —','2p: ↑↓ | ↑↓ | ↑↓'], correct:1, solution:'<p>2p: ↑↓ | ↑ | — has a paired orbital before all three orbitals have one electron each. Hund\'s Rule says fill each singly first.</p>'},
  {id:'p53', difficulty:'medium', type:'concept', tag:'Electron Configuration', q:'Which element has the configuration [Kr] 5s^2 4d^10 5p^6?', choices:['Iodine (Z=53)','Xenon (Z=54)','Tellurium (Z=52)','Cesium (Z=55)'], correct:1, solution:'<p>[Kr]=36, +2(5s)+10(4d)+6(5p) = 36+18 = 54 = <strong>Xenon (Xe, Z=54)</strong> — a noble gas.</p>'},
  {id:'p54', difficulty:'medium', type:'concept', tag:'Quantum Rules', q:'In the ground state of carbon (Z=6), the 2p electrons are:', choices:['Both in the same orbital, opposite spins','In separate 2p orbitals, both spin-up','In separate 2p orbitals, opposite spins','Both in the 2s orbital'], correct:1, solution:'<p>C has 2p^2: Hund\'s Rule says each of the two electrons goes into a separate 2p orbital with the same spin (↑ | ↑ | —).</p>'},
  {id:'p55', difficulty:'medium', type:'concept', tag:'Emission Series', q:'The Lyman series of hydrogen emission lines falls in which region of the spectrum?', choices:['Visible','Ultraviolet','Infrared','X-ray'], correct:1, solution:'<p>Lyman series = transitions to n=1 (ground state). These involve large energy changes, producing short-wavelength UV photons (below 400 nm).</p>'},
  {id:'p56', difficulty:'easy', type:'concept', tag:'Periodic Blocks', q:'Which block of the periodic table contains the alkaline earth metals (Group 2)?', choices:['s-block','p-block','d-block','f-block'], correct:0, solution:'<p>Group 2 elements (Be, Mg, Ca, Sr, Ba) fill the s sublevel — they are in the s-block.</p>'},
  {id:'p57', difficulty:'easy', type:'concept', tag:'Electron Configuration', q:'The noble gas [Ne] has the configuration 1s^2 2s^2 2p^6. Which element comes immediately after Ne and what is its distinguishing sublevel?', choices:['Na — 3s','Mg — 3p','Ar — 3s','Al — 3p'], correct:0, solution:'<p>After Ne (Z=10), the next element is Na (Z=11): [Ne] 3s^1. The distinguishing electron enters the 3s sublevel.</p>'},
  {id:'p58', difficulty:'easy', type:'concept', tag:'Emission Spectra', q:'A photon is emitted when an electron transitions between energy levels. Which description is correct?', choices:['The electron moves to a higher n level and releases a photon','The electron moves to a lower n level and releases a photon','The electron moves to a higher n level and absorbs a photon','The electron gains mass when it drops to a lower level'], correct:1, solution:'<p>Emission occurs when an electron falls to a lower energy level (lower n). The energy difference is released as a photon.</p>'},
  {id:'p59', difficulty:'medium', type:'concept', tag:'Periodic Blocks', q:'Which of the following elements is in the p-block of the periodic table?', choices:['Calcium (Z=20)','Iron (Z=26)','Arsenic (Z=33)','Strontium (Z=38)'], correct:2, solution:'<p>Arsenic (Z=33): [Ar] 4s^2 3d^10 4p^3 — the last electron enters 4p, placing As firmly in the p-block (Group 15). Ca and Sr are s-block; Fe is d-block.</p>'},
  {id:'p60', difficulty:'medium', type:'concept', tag:'Valence Electrons', q:'How many valence electrons does selenium (Z=34) have?', choices:['2','4','6','8'], correct:2, solution:'<p>Se: [Ar] 4s^2 3d^10 4p^4. Valence electrons are in the outermost shell (n=4): 4s^2 + 4p^4 = <strong>6 valence electrons</strong>.</p>'},
  {id:'p61', difficulty:'easy', type:'concept', tag:'Emission Spectra', q:'An absorption spectrum is produced when:', choices:['A hot gas emits light at specific wavelengths','Cool gas atoms absorb specific wavelengths from white light passing through them','Electrons jump to lower energy levels','A solid object is heated until it glows'], correct:1, solution:'<p>Absorption spectra form when electrons in a cool gas absorb photons at specific wavelengths from a background white light — creating dark lines in an otherwise continuous spectrum.</p>'},
  {id:'p62', difficulty:'medium', type:'concept', tag:'Periodic Blocks', q:'Which of these element pairs are in the same block of the periodic table?', choices:['Na and Fe','Ca and Ti','Cl and Br','K and Cr'], correct:2, solution:'<p>Cl (Z=17) and Br (Z=35) are both in the p-block (Group 17, halogens). Na=s, Fe=d; Ca=s, Ti=d; K=s, Cr=d.</p>'},
  {id:'p63', difficulty:'easy', type:'concept', tag:'Quantum Numbers', q:'What does the principal quantum number n primarily determine?', choices:['The shape of the orbital','The orientation of the orbital in space','The energy level and approximate distance from the nucleus','The direction of electron spin'], correct:2, solution:'<p>n determines the energy level (shell). Higher n = higher energy and greater average distance from the nucleus.</p>'},

  // ─── MULTI-STEP (18 problems) ─────────────────────────────────

  {id:'p64', difficulty:'medium', type:'multi', tag:'Multi-step Photon', q:'A photon has a frequency of 6.90 × 10^14 Hz. (a) Is it in the visible range? (b) Calculate its wavelength in nm and energy in joules.', answer:'435', isText:true, tolerance:0, solution:'<p>λ = c/ν = (3.00×10^8)÷(6.90×10^14) = 4.35×10^-7 m = <strong>435 nm (violet, visible)</strong></p><p>E = hν = (6.626×10^-34)(6.90×10^14) = <strong>4.57 × 10^-19 J</strong></p>'},
  {id:'p65', difficulty:'medium', type:'multi', tag:'Electron Config', q:'Write the full electron configuration AND noble-gas shorthand for chlorine (Z = 17). How many valence electrons does it have?', answer:'[Ne] 3s2 3p5', isText:true, tolerance:0, solution:'<p>Full: 1s^2 2s^2 2p^6 3s^2 3p^5 (count: 2+2+6+2+5 = 17 ✓)<br>Shorthand: <strong>[Ne] 3s^2 3p^5</strong><br>Valence electrons: 3s^2 + 3p^5 = <strong>7 valence electrons</strong></p>'},
  {id:'p66', difficulty:'medium', type:'multi', tag:'Orbital Diagram', q:'For the electron configuration [Ar] 4s^2 3d^7, identify the element and draw (describe) the orbital box diagram for the 3d sublevel. How many unpaired electrons are there?', answer:'Cobalt', isText:true, tolerance:0, solution:'<p>[Ar]=18e, +2(4s)+7(3d) = 27 = <strong>Cobalt (Co, Z=27)</strong><br>3d with 7e (Hund\'s): ↑↓ | ↑↓ | ↑↓ | ↑ | ↑<br>Two orbitals have pairs, three are half-filled → <strong>3 unpaired electrons</strong></p>'},
  {id:'p67', difficulty:'medium', type:'multi', tag:'Exceptions', q:'Determine the electron configuration for copper (Z = 29). Explain why it differs from the Aufbau prediction and give the actual configuration.', answer:'[Ar] 4s1 3d10', isText:true, tolerance:0, solution:'<p>Aufbau predicts: [Ar] 4s^2 3d^9<br>Actual: <strong>[Ar] 4s^1 3d^10</strong><br>A fully-filled d sublevel (3d^10) is extra stable — one electron moves from 4s to 3d to achieve this.</p>'},
  {id:'p68', difficulty:'hard', type:'multi', tag:'Bohr Transitions', q:'An electron in a hydrogen atom falls from n = 5 to n = 2. Is this emission or absorption? Calculate the energy of the photon and identify the series.', answer:'emission, Balmer', isText:true, tolerance:0, solution:'<p>n=5 → n=2 is a DOWNWARD transition → <strong>emission</strong></p><p>E5 = -2.18×10^-18/25 = -8.72×10^-20 J</p><p>E2 = -2.18×10^-18/4 = -5.45×10^-19 J</p><p>ΔE = -5.45×10^-19 - (-8.72×10^-20) = -4.58×10^-19 J</p><p>|ΔE| = 4.58×10^-19 J → λ = hc/E = 434 nm (violet, <strong>Balmer series</strong>)</p>'},
  {id:'p69', difficulty:'hard', type:'multi', tag:'Quantum Rules', q:'State which rule is violated in each case, and why: (A) 2p: ↑↓ | ↑ | — (only 3 electrons, with one pair already formed). (B) 3d: ↑ | ↑ | ↑ | ↑ | ↑↑ (a 3d sublevel with one orbital holding 2 electrons of the same spin).', answer:"Hund's, Pauli", isText:true, tolerance:0, solution:'<p>(A) Violates <strong>Hund\'s Rule</strong>: with only 3 electrons in p, each orbital should have one (↑ ↑ ↑), not a pair plus one.<br>(B) Violates <strong>Pauli Exclusion</strong>: two electrons in the same orbital must have OPPOSITE spins — ↑↑ in one orbital is forbidden.</p>'},
  {id:'p70', difficulty:'medium', type:'multi', tag:'Electron Config', q:'Germanium (Z = 32) is a semiconductor in the p-block. Write its noble-gas shorthand and determine how many electrons are in the 4p sublevel.', answer:'[Ar] 4s2 3d10 4p2', isText:true, tolerance:0, solution:'<p>After [Ar] (Z=18): fill 4s^2 (+2=20), 3d^10 (+10=30), 4p^2 (+2=32) ✓<br>Noble-gas shorthand: <strong>[Ar] 4s^2 3d^10 4p^2</strong><br>Electrons in 4p: <strong>2</strong></p>'},
  {id:'p71', difficulty:'medium', type:'multi', tag:'Bohr Transitions', q:'A photon of UV light has wavelength 121 nm (the Lyman-α line of hydrogen). (a) Calculate frequency and energy. (b) Which transition produces it?', answer:'2.48e15', isText:true, tolerance:0, solution:'<p>ν = (3.00×10^8)÷(121×10^-9) = <strong>2.48×10^15 Hz</strong></p><p>E = hν = (6.626×10^-34)(2.48×10^15) = <strong>1.64×10^-18 J</strong></p><p>This is the <strong>n=2 → n=1 Lyman-α transition</strong> (Lyman series, UV).</p>'},
  {id:'p72', difficulty:'medium', type:'multi', tag:'Orbital Diagram', q:'Phosphorus (Z = 15) is in period 3. Write its noble-gas shorthand, draw the 3p orbital box diagram (describe in words), and count the unpaired electrons.', answer:'[Ne] 3s2 3p3', isText:true, tolerance:0, solution:'<p>Full: 1s^2 2s^2 2p^6 3s^2 3p^3 (count: 2+2+6+2+3 = 15 ✓)<br>Noble-gas shorthand: <strong>[Ne] 3s^2 3p^3</strong><br>3p with 3 electrons (Hund\'s rule): ↑ | ↑ | ↑ — each orbital gets one electron first.<br>Unpaired electrons: <strong>3</strong></p>'},
  {id:'p73', difficulty:'medium', type:'multi', tag:'Electron Config', q:'Vanadium (Z=23) is a transition metal. Write its full electron configuration and noble-gas shorthand. How many unpaired electrons does it have?', answer:'[Ar] 4s2 3d3', isText:true, tolerance:0, solution:'<p>Full: 1s^2 2s^2 2p^6 3s^2 3p^6 4s^2 3d^3 (count: 2+2+6+2+6+2+3 = 23 ✓)<br>Noble-gas shorthand: <strong>[Ar] 4s^2 3d^3</strong><br>3d with 3 electrons (Hund\'s): ↑ | ↑ | ↑ | — | — → <strong>3 unpaired electrons</strong></p>'},
  {id:'p74', difficulty:'hard', type:'multi', tag:'Multi-step Photon', q:'Calculate the frequency and energy of a photon of violet light with λ = 410 nm. Which Balmer line is this (what transition produces it)?', answer:'7.32e14', isText:true, tolerance:0, solution:'<p>ν = (3.00×10^8)÷(410×10^-9) = <strong>7.32×10^14 Hz</strong><br>E = hν = (6.626×10^-34)(7.32×10^14) = <strong>4.85×10^-19 J</strong><br>This is the Balmer H-delta line, produced by the <strong>n=6 → n=2</strong> transition.</p>'},
  {id:'p75', difficulty:'medium', type:'multi', tag:'Electron Config', q:'For bromine (Z=35): (a) Write the noble-gas shorthand. (b) Identify the block. (c) Count the valence electrons.', answer:'[Ar] 4s2 3d10 4p5', isText:true, tolerance:0, solution:'<p>Shorthand: <strong>[Ar] 4s^2 3d^10 4p^5</strong><br>Block: <strong>p-block</strong> (last electron enters 4p)<br>Valence electrons: 4s^2 + 4p^5 = <strong>7 valence electrons</strong></p>'},
  {id:'p76', difficulty:'medium', type:'multi', tag:'Electron Config', q:'Iodine (Z=53) is in period 5. Write its noble-gas shorthand, count its valence electrons, and state what period-5 sublevel is filling.', answer:'[Kr] 5s2 4d10 5p5', isText:true, tolerance:0, solution:'<p>Shorthand: <strong>[Kr] 5s^2 4d^10 5p^5</strong><br>Valence electrons: 5s^2 + 5p^5 = <strong>7 valence electrons</strong><br>Sublevel filling: <strong>5p</strong> (I is the 5th element filling 5p)</p>'},
  {id:'p77', difficulty:'hard', type:'multi', tag:'Bohr Transitions', q:'An electron in hydrogen falls from n = 6 to n = 2. Calculate |ΔE| and the wavelength. Use Eₙ = -2.18 × 10^-18 / n^2.', answer:'410', isText:true, tolerance:0, solution:'<p>E6 = -2.18×10^-18/36 = -6.056×10^-20 J</p><p>E2 = -2.18×10^-18/4 = -5.45×10^-19 J</p><p>ΔE = -5.45×10^-19-(-6.056×10^-20) = -4.844×10^-19 J</p><p>λ = hc/|ΔE| = (6.626×10^-34×3.00×10^8)÷(4.844×10^-19) = <strong>410 nm</strong> (violet Balmer line)</p>'},
  {id:'p78', difficulty:'easy', type:'multi', tag:'Quantum Rules', q:'Helium (Z=2) has 2 electrons. Draw its orbital box diagram (describe it in words), state which sublevel holds both electrons, and explain why the two electrons must have opposite spins.', answer:'1s full both in 1s', isText:true, tolerance:0, solution:'<p>Helium: 1s^2<br>Orbital box diagram: 1s: ↑↓ (one orbital, completely filled)<br>Both electrons are in the <strong>1s sublevel</strong>.<br>They must have opposite spins (↑↓) because of the <strong>Pauli Exclusion Principle</strong> — no two electrons in the same orbital can have the same spin direction.</p>'},
  {id:'p79', difficulty:'hard', type:'multi', tag:'Orbital Diagram', q:'Nickel (Z=28) is a transition metal. Write its noble-gas shorthand, draw the 3d orbital box diagram (describe it in words), and count unpaired electrons.', answer:'[Ar] 4s2 3d8', isText:true, tolerance:0, solution:'<p>Shorthand: <strong>[Ar] 4s^2 3d^8</strong><br>3d with 8e: first pass fills all 5 orbitals singly (5↑), second pass adds 3 more ↓: ↑↓|↑↓|↑↓|↑|↑<br>Unpaired electrons: <strong>2</strong> (the last two orbitals have one electron each)</p>'},
  {id:'p80', difficulty:'hard', type:'multi', tag:'Multi-step Photon', q:'A radio wave has a frequency of 1.00 × 10^8 Hz. Calculate its wavelength in meters and compare its photon energy to that of visible light at 500 nm. Which has more energy per photon and by roughly what factor?', answer:'3 meters', isText:true, tolerance:0, solution:'<p>λ_radio = c/ν = (3.00×10^8)÷(1.00×10^8) = <strong>3.00 m</strong><br>E_radio = hν = (6.626×10^-34)(1.00×10^8) = 6.63×10^-26 J<br>E_visible = hc/λ = (6.626×10^-34×3.00×10^8)÷(500×10^-9) = 3.98×10^-19 J<br>Ratio: 3.98×10^-19 ÷ 6.63×10^-26 ≈ 6×10^6 — <strong>visible light has about 6 million times more energy per photon than the radio wave.</strong></p>'},
  {id:'p81', difficulty:'medium', type:'multi', tag:'Exceptions', q:'Zinc (Z=30) has a completely filled 3d sublevel. Write its noble-gas shorthand, explain why Zn is NOT considered a typical transition metal, and give the number of unpaired electrons.', answer:'[Ar] 4s2 3d10', isText:true, tolerance:0, solution:'<p>Shorthand: <strong>[Ar] 4s^2 3d^10</strong><br>Zn is not a typical transition metal because its 3d sublevel is <strong>completely filled</strong> — transition metals are defined by partially filled d orbitals in the element or its common ions. Zn has <strong>0 unpaired electrons</strong> (all sublevels are completely filled or paired).</p>'},

  // ═══════════════════ EXPANSION BATCH — 60 problems (20 easy / 25 medium / 15 hard) ═══════════════════

  // ── EASY (20) ──
  {id:'p82', difficulty:'easy', type:'calc', tag:'Wave Equations', q:'What is the frequency (in Hz) of light with a wavelength of 500.0 nm?', answer:6.00e14, unit:'Hz', tolerance:1e13, solution:'<p>ν = c/λ = (3.00×10^8) ÷ (500.0×10^-9) = <strong>6.00 × 10^14 Hz</strong></p>'},
  {id:'p83', difficulty:'easy', type:'calc', tag:'Wave Equations', q:'What is the wavelength (in nm) of light with a frequency of 6.00 × 10^14 Hz?', answer:500.0, unit:'nm', tolerance:2, solution:'<p>λ = c/ν = (3.00×10^8) ÷ (6.00×10^14) = <strong>500.0 nm</strong></p>'},
  {id:'p84', difficulty:'easy', type:'calc', tag:'Photon Energy', q:'What is the energy (in J) of a photon of light with a frequency of 4.00 × 10^14 Hz?', answer:2.65e-19, unit:'J', tolerance:5e-21, solution:'<p>E = hν = (6.626×10^-34)(4.00×10^14) = <strong>2.65 × 10^-19 J</strong></p>'},
  {id:'p85', difficulty:'easy', type:'calc', tag:'Bohr Model', q:'Calculate the energy (in J) of the hydrogen electron at n = 5. Use Eₙ = -2.18 × 10^-18 / n^2.', answer:-8.72e-20, unit:'J', tolerance:2e-21, solution:'<p>E5 = -2.18×10^-18 ÷ (5^2) = -2.18×10^-18 ÷ 25 = <strong>-8.72 × 10^-20 J</strong></p>'},
  {id:'p86', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'How many orbitals are in the n = 1 energy level?', answer:1, unit:'orbitals', tolerance:0, solution:'<p>n=1 has only the 1s sublevel, which is <strong>1 orbital</strong>.</p>'},
  {id:'p87', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the n = 1 energy level?', answer:2, unit:'electrons', tolerance:0, solution:'<p>n=1: 1s(2) = <strong>2 electrons</strong> — this is why period 1 has only 2 elements (H and He).</p>'},
  {id:'p88', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the 3p sublevel?', answer:6, unit:'electrons', tolerance:0, solution:'<p>Every p sublevel has 3 orbitals × 2 electrons each = <strong>6 electrons maximum</strong>.</p>'},
  {id:'p89', difficulty:'easy', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the 4f sublevel?', answer:14, unit:'electrons', tolerance:0, solution:'<p>Every f sublevel has 7 orbitals × 2 electrons each = <strong>14 electrons maximum</strong>.</p>'},
  {id:'p90', difficulty:'easy', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does fluorine (Z = 9) have in its ground state?', answer:1, unit:'unpaired electrons', tolerance:0, solution:'<p>F: [He] 2s^2 2p^5. 2p diagram: ↑↓ | ↑↓ | ↑ → <strong>1 unpaired electron</strong>.</p>'},
  {id:'p91', difficulty:'easy', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does carbon (Z = 6) have in its ground state?', answer:2, unit:'unpaired electrons', tolerance:0, solution:'<p>C: [He] 2s^2 2p^2. 2p diagram (Hund\'s rule): ↑ | ↑ | — → <strong>2 unpaired electrons</strong>.</p>'},
  {id:'p92', difficulty:'easy', type:'concept', tag:'EM Spectrum', q:'Which type of electromagnetic radiation has the longest wavelength?', choices:['Radio waves','Visible light','X-rays','Gamma rays'], correct:0, solution:'<p>Radio waves have the longest wavelengths (and lowest energy) of the four options listed — gamma rays have the shortest wavelength and highest energy.</p>'},
  {id:'p93', difficulty:'easy', type:'concept', tag:'Orbital Shapes', q:'The s sublevel contains how many orbitals?', choices:['1','3','5','7'], correct:0, solution:'<p>The s sublevel always has exactly <strong>1 orbital</strong>, which is spherical and holds up to 2 electrons.</p>'},
  {id:'p94', difficulty:'easy', type:'concept', tag:'Orbital Shapes', q:'The p sublevel contains how many orbitals?', choices:['1','3','5','7'], correct:1, solution:'<p>The p sublevel always has <strong>3 orbitals</strong>, oriented along the x, y, and z axes, holding up to 6 electrons total.</p>'},
  {id:'p95', difficulty:'easy', type:'concept', tag:'Aufbau', q:'Electrons fill orbitals starting from lowest to highest energy according to the:', choices:['Hund\'s Rule','Pauli Exclusion Principle','Aufbau Principle','Heisenberg Uncertainty Principle'], correct:2, solution:'<p>The Aufbau Principle ("building up") states that electrons occupy the lowest-energy available orbitals first before filling higher-energy ones.</p>'},
  {id:'p96', difficulty:'easy', type:'concept', tag:'Quantum Rules', q:'What is the maximum number of electrons that can occupy a single orbital?', choices:['1','2','3','4'], correct:1, solution:'<p>Every orbital, regardless of sublevel, holds a maximum of 2 electrons — and those two must have opposite spins.</p>'},
  {id:'p97', difficulty:'easy', type:'concept', tag:'Noble Gas Notation', q:'Which noble gas has the configuration 1s^2 2s^2 2p^6 3s^2 3p^6?', choices:['Neon','Argon','Krypton','Xenon'], correct:1, solution:'<p>Counting the electrons: 2+2+6+2+6 = 18. The noble gas with 18 electrons (Z=18) is <strong>argon</strong>.</p>'},
  {id:'p98', difficulty:'easy', type:'concept', tag:'Emission Spectra', q:'An electron dropping from a higher to a lower energy level releases energy in the form of a:', choices:['Neutron','Photon','Proton','Isotope'], correct:1, solution:'<p>When an electron falls to a lower energy level, it releases the energy difference as a photon of light — the basis of atomic emission spectra.</p>'},
  {id:'p99', difficulty:'easy', type:'concept', tag:'Aufbau', q:'Which sublevel is always filled first in any atom, since it has the lowest possible energy?', choices:['1s','2s','2p','3s'], correct:0, solution:'<p>The 1s sublevel has the lowest energy of all sublevels and is always the first to be filled, starting with hydrogen.</p>'},
  {id:'p100', difficulty:'easy', type:'concept', tag:'Quantum Rules', q:'How many electrons does a neutral atom of helium (Z=2) have in the 1s orbital?', choices:['0','1','2','4'], correct:2, solution:'<p>Helium has 2 electrons total, and since the 1s orbital is the only occupied orbital, both electrons are in 1s: 1s^2.</p>'},
  {id:'p101', difficulty:'easy', type:'concept', tag:'Orbital Shapes', q:'Which of the following correctly lists sublevel types in order of increasing number of orbitals?', choices:['s < p < d < f','f < d < p < s','p < s < d < f','s < d < p < f'], correct:0, solution:'<p>s has 1 orbital, p has 3, d has 5, and f has 7 — so the correct increasing order is s < p < d < f.</p>'},

  // ── MEDIUM (25) ──
  {id:'p102', difficulty:'medium', type:'calc', tag:'Photon Energy', q:'What is the wavelength (in nm) of a photon with an energy of 5.00 × 10^-19 J?', answer:397.6, unit:'nm', tolerance:3, solution:'<p>ν = E/h = (5.00×10^-19)÷(6.626×10^-34) = 7.547×10^14 Hz<br>λ = c/ν = (3.00×10^8)÷(7.547×10^14) = 3.976×10^-7 m = <strong>397.6 nm</strong></p>'},
  {id:'p103', difficulty:'medium', type:'calc', tag:'Photon Energy', q:'What is the energy (in J) of a photon of light with a wavelength of 550 nm?', answer:3.61e-19, unit:'J', tolerance:5e-21, solution:'<p>ν = (3.00×10^8)÷(550×10^-9) = 5.455×10^14 Hz<br>E = hν = (6.626×10^-34)(5.455×10^14) = <strong>3.61 × 10^-19 J</strong></p>'},
  {id:'p104', difficulty:'medium', type:'calc', tag:'Bohr Model', q:'Calculate the energy (in J) of the hydrogen electron at n = 6. Use Eₙ = -2.18 × 10^-18 / n^2.', answer:-6.06e-20, unit:'J', tolerance:2e-21, solution:'<p>E6 = -2.18×10^-18 ÷ (6^2) = -2.18×10^-18 ÷ 36 = <strong>-6.06 × 10^-20 J</strong></p>'},
  {id:'p105', difficulty:'medium', type:'calc', tag:'Bohr Model', q:'What is the energy (in J) of the photon emitted when a hydrogen electron falls from n = 4 to n = 1? Give your answer as a positive number.', answer:2.04e-18, unit:'J', tolerance:3e-20, solution:'<p>E4 = -1.36×10^-19 J. E1 = -2.18×10^-18 J.<br>ΔE = E1 - E4 = -2.18×10^-18 - (-1.36×10^-19) = -2.04×10^-18 J<br>The photon\'s energy is the magnitude: <strong>2.04 × 10^-18 J</strong></p>'},
  {id:'p106', difficulty:'medium', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does cobalt (Z = 27) have in its ground state?', answer:3, unit:'unpaired electrons', tolerance:0, solution:'<p>Co: [Ar] 4s^2 3d^7. Filling 3d with Hund\'s rule: all 5 orbitals get 1 electron first (5↑), then the remaining 2 electrons pair up: ↑↓|↑↓|↑|↑|↑ → <strong>3 unpaired electrons</strong>.</p>'},
  {id:'p107', difficulty:'medium', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does titanium (Z = 22) have in its ground state?', answer:2, unit:'unpaired electrons', tolerance:0, solution:'<p>Ti: [Ar] 4s^2 3d^2. 3d diagram (Hund\'s rule): ↑ | ↑ | — | — | — → <strong>2 unpaired electrons</strong>.</p>'},
  {id:'p108', difficulty:'medium', type:'concept', tag:'EM Spectrum', q:'Which of the following correctly ranks these types of EM radiation from lowest to highest energy?', choices:['Radio < Infrared < Visible < UV','UV < Visible < Infrared < Radio','Visible < UV < Radio < Infrared','Infrared < Radio < UV < Visible'], correct:0, solution:'<p>Energy increases as wavelength decreases: Radio (longest λ) < Infrared < Visible < UV (shortest λ, highest energy) among these four.</p>'},
  {id:'p109', difficulty:'medium', type:'concept', tag:'Quantum Rules', q:'Why can\'t two electrons in the same orbital have the same spin?', choices:['Because of the Aufbau Principle','Because of the Pauli Exclusion Principle','Because of Hund\'s Rule','Because orbitals only hold 1 electron'], correct:1, solution:'<p>The Pauli Exclusion Principle requires that any two electrons sharing the same orbital must have opposite spins — no two electrons in an atom can have an identical set of quantum numbers.</p>'},
  {id:'p110', difficulty:'medium', type:'concept', tag:'Periodic Blocks', q:'Which sublevel is filling in the lanthanide series (elements 58–71)?', choices:['4f','5d','6s','5f'], correct:0, solution:'<p>The lanthanide series corresponds to the filling of the 4f sublevel, which holds up to 14 electrons across these 14 elements.</p>'},
  {id:'p111', difficulty:'medium', type:'concept', tag:'Bohr Model', q:'An electron absorbs a photon and jumps from n=2 to n=5. What must be true about this photon\'s energy compared to a photon causing an n=2 → n=3 transition?', choices:['It must be smaller','It must be larger, since n=2→n=5 spans a bigger energy gap','It must be exactly equal','Energy is not involved in absorption'], correct:1, solution:'<p>A bigger jump in energy level number corresponds to a bigger energy gap. Since n=2→n=5 spans more levels than n=2→n=3, it requires a higher-energy (and therefore higher-frequency, shorter-wavelength) photon.</p>'},
  {id:'p112', difficulty:'medium', type:'concept', tag:'Exceptions', q:'Molybdenum (Z=42) is an exception to the Aufbau principle, similar to chromium. What is its likely actual ground-state configuration pattern?', choices:['[Kr] 5s^2 4d^4','[Kr] 5s^1 4d^5 (half-filled d is extra stable)','[Kr] 5s^0 4d^6','[Kr] 5s^2 4d^5'], correct:1, solution:'<p>Like chromium, molybdenum gains extra stability from a half-filled d sublevel. One electron moves from 5s into 4d, giving [Kr] 5s^1 4d^5 instead of the Aufbau-predicted [Kr] 5s^2 4d^4.</p>'},
  {id:'p113', difficulty:'medium', type:'calc', tag:'Valence Electrons', q:'How many valence electrons does arsenic (Z=33) have?', answer:5, unit:'valence electrons', tolerance:0, solution:'<p>As: [Ar] 4s^2 3d^10 4p^3. Valence electrons are in the outermost shell (n=4): 4s^2 + 4p^3 = <strong>5 valence electrons</strong>.</p>'},
  {id:'p114', difficulty:'medium', type:'calc', tag:'Valence Electrons', q:'How many valence electrons does tin (Sn, Z=50) have?', answer:4, unit:'valence electrons', tolerance:0, solution:'<p>Sn: [Kr] 5s^2 4d^10 5p^2. Valence electrons are in the outermost shell (n=5): 5s^2 + 5p^2 = <strong>4 valence electrons</strong>.</p>'},
  {id:'p115', difficulty:'medium', type:'concept', tag:'Periodic Blocks', q:'Which of the following correctly identifies the block of strontium (Z=38)?', choices:['s-block','p-block','d-block','f-block'], correct:0, solution:'<p>Strontium is in Group 2, where the outermost electrons fill the s sublevel (5s^2) — placing it in the s-block.</p>'},
  {id:'p116', difficulty:'medium', type:'concept', tag:'Periodic Blocks', q:'Which of the following correctly identifies the block of gold (Z=79, [Xe]6s^1 4f^14 5d^10)?', choices:['s-block','p-block','d-block','f-block'], correct:2, solution:'<p>Even though gold\'s outermost written sublevel is 6s^1, the last electron added following the periodic table\'s filling pattern enters 5d, placing gold in the d-block (transition metals).</p>'},
  {id:'p117', difficulty:'medium', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the 5f sublevel?', answer:14, unit:'electrons', tolerance:0, solution:'<p>Every f sublevel has 7 orbitals × 2 electrons each = <strong>14 electrons maximum</strong>, regardless of the principal energy level.</p>'},
  {id:'p118', difficulty:'medium', type:'concept', tag:'Electron Configuration', q:'Which element has the configuration [Ar] 4s^2 3d^10 4p^6?', choices:['Selenium','Bromine','Krypton','Rubidium'], correct:2, solution:'<p>[Ar]=18e, +2(4s)+10(3d)+6(4p) = 18+18 = 36 electrons. The element with 36 electrons is krypton (Z=36), a noble gas.</p>'},
  {id:'p119', difficulty:'medium', type:'concept', tag:'Exceptions', q:'A student says "the 4s sublevel always fills completely before any 3d electrons are added." Is this always true for chromium and copper?', choices:['No — Cr and Cu are exceptions where only 1 electron occupies 4s while 3d gets an extra electron', 'Yes, this is always true without exception', 'No, 4s never fills before 3d', 'Yes, but only for chromium'], correct:0, solution:'<p>Chromium and copper are the classic exceptions: instead of the predicted 4s^2, only 1 electron stays in 4s, and the extra electron shifts into 3d to achieve a more stable half-filled (Cr, 3d^5) or fully-filled (Cu, 3d^10) sublevel.</p>'},
  {id:'p120', difficulty:'medium', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does zirconium (Z = 40) have in its ground state? (Zr: [Kr] 5s^2 4d^2)', answer:2, unit:'unpaired electrons', tolerance:0, solution:'<p>4d^2 with Hund\'s rule: ↑ | ↑ | — | — | — → <strong>2 unpaired electrons</strong>. The filled 5s^2 contributes 0 unpaired electrons.</p>'},
  {id:'p121', difficulty:'medium', type:'concept', tag:'Noble Gas Notation', q:'Which of the following is the correct noble-gas shorthand for potassium (Z=19)?', choices:['[Ne] 4s^1','[Ar] 4s^1','[Ar] 3d^1','[Kr] 4s^1'], correct:1, solution:'<p>Potassium (Z=19) has 1 electron beyond the argon core (Z=18). Its correct noble-gas shorthand is [Ar] 4s^1 — the 19th electron enters the 4s sublevel, not 3d.</p>'},
  {id:'p122', difficulty:'medium', type:'calc', tag:'Bohr Model', q:'What is the energy (in J) released when a hydrogen electron falls from n = 4 to n = 2? Give your answer as a positive number.', answer:4.09e-19, unit:'J', tolerance:5e-21, solution:'<p>E4 = -1.36×10^-19 J. E2 = -5.45×10^-19 J.<br>ΔE = E2 - E4 = -5.45×10^-19 - (-1.36×10^-19) = -4.09×10^-19 J<br>The photon\'s energy is the magnitude: <strong>4.09 × 10^-19 J</strong></p>'},
  {id:'p123', difficulty:'medium', type:'concept', tag:'Electron Configuration', q:'Which statement correctly compares the energy of a 3s electron to a 3p electron in the same atom?', choices:['3s electrons generally have slightly lower energy than 3p electrons in the same atom','3p electrons always have lower energy than 3s','They always have identical energy','Energy cannot be compared between sublevels'], correct:0, solution:'<p>Within the same principal energy level, sublevels have slightly different energies due to electron shielding and penetration effects: s < p < d < f. So a 3s electron has slightly lower energy than a 3p electron.</p>'},
  {id:'p124', difficulty:'medium', type:'calc', tag:'Ions', q:'Neutral iron (Z=26) has the configuration [Ar] 4s^2 3d^6. If electrons are removed from 4s first, how many total electrons does the Fe^2+ ion have?', answer:24, unit:'electrons', tolerance:0, solution:'<p>Fe has 26 electrons. Forming Fe^2+ removes 2 electrons, both from the 4s sublevel (giving [Ar] 3d^6). Total electrons remaining: 26 - 2 = <strong>24 electrons</strong>.</p>'},
  {id:'p125', difficulty:'medium', type:'concept', tag:'Aufbau', q:'Which of the following pairs is correctly matched?', choices:['Aufbau Principle — electrons fill lowest energy orbitals first','Hund\'s Rule — orbitals fill in order of increasing n','Pauli Exclusion — electrons always pair immediately','None of these are correctly matched'], correct:0, solution:'<p>The Aufbau Principle states that electrons fill the lowest-energy orbitals available first. Hund\'s Rule is about spreading electrons across orbitals of the same sublevel before pairing; Pauli Exclusion is about opposite spins, not immediate pairing.</p>'},
  {id:'p126', difficulty:'medium', type:'calc', tag:'Bohr Model', q:'What is the wavelength (in nm) of a photon emitted when a hydrogen electron falls from n = 3 to n = 1?', answer:102.6, unit:'nm', tolerance:1, solution:'<p>E3 = -2.42×10^-19 J. E1 = -2.18×10^-18 J.<br>ΔE = E1 - E3 = -1.938×10^-18 J → magnitude 1.938×10^-18 J<br>λ = hc/E = (6.626×10^-34 × 3.00×10^8) ÷ (1.938×10^-18) = <strong>102.6 nm</strong> (Lyman series, UV)</p>'},

  // ── HARD (15) ──
  {id:'p127', difficulty:'hard', type:'multi', tag:'Bohr Transitions', q:'A hydrogen electron falls from n = 7 to n = 2, emitting a photon. Calculate the photon\'s wavelength in nm.', answer:'397', isText:true, tolerance:0, solution:'<p>E7 = -4.45×10^-20 J. E2 = -5.45×10^-19 J.<br>ΔE = E2 - E7 = -5.01×10^-19 J → magnitude 5.01×10^-19 J<br>λ = hc/E = (6.626×10^-34 × 3.00×10^8) ÷ (5.01×10^-19) = <strong>397 nm</strong> (edge of the Balmer series)</p>'},
  {id:'p128', difficulty:'hard', type:'multi', tag:'Exceptions', q:'Silver (Ag, Z=47) is a well-known exception to the Aufbau principle, similar to copper. Regular Aufbau predicts [Kr] 5s^2 4d^9. Write the actual ground-state configuration.', answer:'[Kr] 5s1 4d10', isText:true, tolerance:0, solution:'<p>Like copper, silver shifts one electron from 5s into 4d to complete a fully-filled (and extra stable) d sublevel. Actual configuration: <strong>[Kr] 5s^1 4d^10</strong>, not the Aufbau-predicted [Kr] 5s^2 4d^9.</p>'},
  {id:'p129', difficulty:'hard', type:'calc', tag:'Bohr Model', q:'What is the minimum energy (in J) needed to ionize a hydrogen electron starting from n = 4? (Ionization energy from level n equals |Eₙ|, since the electron ends at E = 0.)', answer:1.36e-19, unit:'J', tolerance:3e-21, solution:'<p>Ionizing an electron means removing it completely, ending at E=0 (n=∞). The energy required equals the magnitude of the electron\'s starting energy: |E4| = 2.18×10^-18 ÷ 16 = <strong>1.36 × 10^-19 J</strong>.</p>'},
  {id:'p130', difficulty:'hard', type:'multi', tag:'Bohr Transitions', q:'Compare two hydrogen transitions ending at n=1: Transition A is n=3→n=1, Transition B is n=2→n=1. Calculate the energy released by Transition A (in J), and determine which transition releases more energy.', answer:'1.94e-18', isText:true, tolerance:0, solution:'<p>Transition A: |E1 - E3| = |-2.18×10^-18 - (-2.42×10^-19)| = <strong>1.94 × 10^-18 J</strong><br>Transition B: |E1 - E2| = |-2.18×10^-18 - (-5.45×10^-19)| = 1.64×10^-18 J<br>Transition A releases more energy because it spans a bigger drop in energy level.</p>'},
  {id:'p131', difficulty:'hard', type:'calc', tag:'Bohr Model', q:'A photon with wavelength 91.2 nm strikes a ground-state hydrogen atom (n=1) and ionizes it with no excess kinetic energy. Calculate the photon\'s energy in J, and confirm it matches the n=1 ionization energy (2.18 × 10^-18 J).', answer:2.18e-18, unit:'J', tolerance:0.03e-18, solution:'<p>E = hc/λ = (6.626×10^-34 × 3.00×10^8) ÷ (91.2×10^-9) = <strong>2.18 × 10^-18 J</strong>, which matches |E1| exactly — confirming this wavelength (the Lyman series limit) is exactly enough to ionize hydrogen from its ground state.</p>'},
  {id:'p132', difficulty:'hard', type:'multi', tag:'Bohr Transitions', q:'A photon of wavelength 95.0 nm is absorbed by a ground-state hydrogen atom. Determine which energy level (n) the electron is excited to.', answer:'5', isText:true, tolerance:0, solution:'<p>E_photon = hc/λ = (6.626×10^-34 × 3.00×10^8) ÷ (95.0×10^-9) = 2.093×10^-18 J<br>This energy must equal |E1 - En|. Testing n=5: |E1 - E5| = |-2.18×10^-18-(-8.72×10^-20)| = 2.093×10^-18 J ✓ — the electron reaches <strong>n = 5</strong>.</p>'},
  {id:'p133', difficulty:'hard', type:'multi', tag:'Bohr Transitions', q:'Calculate the wavelength (in nm) of a photon needed to excite a hydrogen electron from n=1 directly to n=4.', answer:'97.3', isText:true, tolerance:0, solution:'<p>ΔE = E4 - E1 = -1.36×10^-19 - (-2.18×10^-18) = 2.04×10^-18 J<br>λ = hc/E = (6.626×10^-34 × 3.00×10^8) ÷ (2.04×10^-18) = <strong>97.3 nm</strong> (Lyman series, UV)</p>'},
  {id:'p134', difficulty:'hard', type:'calc', tag:'Orbital Counting', q:'How many total orbitals are in the n = 4 energy level (count all s, p, d, f orbitals combined)?', answer:16, unit:'orbitals', tolerance:0, solution:'<p>n=4 has: 4s(1) + 4p(3) + 4d(5) + 4f(7) = <strong>16 orbitals</strong> total.</p>'},
  {id:'p135', difficulty:'hard', type:'multi', tag:'Electron Config', q:'A student incorrectly writes the electron configuration of scandium (Z=21) as [Ar] 3d^3, skipping 4s entirely. Give the correct configuration.', answer:'[Ar] 4s2 3d1', isText:true, tolerance:0, solution:'<p>The student\'s error skips the Aufbau order — 4s fills before 3d. The correct configuration is <strong>[Ar] 4s^2 3d^1</strong> (count: 18+2+1 = 21 ✓), not [Ar] 3d^3 (which would only total 21 electrons by coincidence but places them in the wrong sublevels).</p>'},
  {id:'p136', difficulty:'hard', type:'multi', tag:'Bohr Model', q:'Compare the ionization energy needed to remove an electron from n=1 versus from n=3 in hydrogen. Calculate the difference between the two ionization energies, in J.', answer:'1.94e-18', isText:true, tolerance:0, solution:'<p>Ionization energy from n=1: |E1| = 2.18×10^-18 J. From n=3: |E3| = 2.42×10^-19 J.<br>Difference = 2.18×10^-18 - 2.42×10^-19 = <strong>1.94 × 10^-18 J</strong>. Removing the n=1 electron requires far more energy since it is much more tightly bound.</p>'},
  {id:'p137', difficulty:'hard', type:'concept', tag:'Periodic Blocks', q:'Tungsten\'s configuration is [Xe] 6s^2 4f^14 5d^4. Which block does tungsten belong to, and why?', choices:['d-block, because the last electron added enters the 5d sublevel','f-block, because it contains 4f^14 electrons','s-block, because the configuration starts with 6s^2','p-block, because tungsten is a metal'], correct:0, solution:'<p>Even though the 4f sublevel appears in the written configuration, it was filled by earlier elements (the lanthanides). Tungsten\'s own distinguishing electron enters the 5d sublevel, placing it in the d-block (transition metals).</p>'},
  {id:'p138', difficulty:'hard', type:'concept', tag:'Exceptions', q:'A student claims manganese (Mn, Z=25) has 5 unpaired electrons and is therefore "an Aufbau exception like chromium." Evaluate this claim.', choices:['The claim is false — Mn\'s normal Aufbau-predicted configuration IS [Ar] 4s^2 3d^5, so no exception/electron-jump is needed to reach a half-filled d; only Cr and Cu require an actual jump from the predicted pattern','The claim is true — Mn is exactly like Cr','The claim is false because Mn does not have 5 unpaired electrons','The claim is true because all half-filled sublevels are exceptions'], correct:0, solution:'<p>Manganese does have 5 unpaired electrons (3d^5), but standard Aufbau filling naturally predicts [Ar] 4s^2 3d^5 for Z=25 — no electron needs to "jump" from 4s to 3d, unlike the true exceptions chromium and copper.</p>'},
  {id:'p139', difficulty:'hard', type:'concept', tag:'Bohr Model', q:'Which of the following correctly explains why removing an electron from n=1 in hydrogen requires much more energy than removing one from n=4?', choices:['Electrons closer to the nucleus (lower n) are held more tightly by the attractive positive charge, requiring more energy to remove','Electrons in n=1 have more mass than electrons in n=4','Ionization energy is unrelated to electron position','Electrons in n=4 are chemically bonded and cannot be removed'], correct:0, solution:'<p>The closer an electron is to the positively charged nucleus, the stronger the electrostatic attraction holding it in place, and the more energy is required to remove it completely. This is why |E1| >> |E4|.</p>'},
  {id:'p140', difficulty:'hard', type:'concept', tag:'Quantum Rules', q:'Which combination of quantum numbers describes an IMPOSSIBLE electron arrangement?', choices:['n=2, sublevel=p, 2 electrons in the same orbital with opposite spins','n=3, sublevel=d, an orbital containing 2 electrons with the SAME spin','n=1, sublevel=s, 2 electrons with opposite spins','n=4, sublevel=f, an orbital with only 1 electron'], correct:1, solution:'<p>Two electrons sharing an orbital with the SAME spin violates the Pauli Exclusion Principle — any two electrons in the same orbital must have opposite spins. The other three options all describe valid, allowed arrangements.</p>'},
  {id:'p141', difficulty:'hard', type:'multi', tag:'Bohr Transitions', q:'A hydrogen electron falls to n = 2 after being excited to a higher level, emitting a photon of wavelength 486 nm. Using Eₙ = -2.18 × 10^-18 / n^2, determine the original energy level (n) it fell from.', answer:'4', isText:true, tolerance:0, solution:'<p>E_photon = hc/λ = (6.626×10^-34 × 3.00×10^8) ÷ (486×10^-9) = 4.09×10^-19 J (emitted)<br>The electron started at En = E2 + 4.09×10^-19 = -5.45×10^-19 + 4.09×10^-19 = -1.36×10^-19 J<br>Solving n^2 = -2.18×10^-18 / En = 16 → <strong>n = 4</strong> (this is the famous Hβ Balmer line).</p>'},

  // ═══════════════════ HARD EXPANSION BATCH — 30 additional hard problems ═══════════════════
  {id:'p142', difficulty:'hard', type:'calc', tag:'Unpaired Electrons', q:'Niobium (Nb, Z=41) has the exception configuration [Kr] 5s^1 4d^4. How many total unpaired electrons does it have?', answer:5, unit:'unpaired electrons', tolerance:0, solution:'<p>5s^1 contributes 1 unpaired electron. 4d^4 (Hund\'s rule, 4 orbitals singly filled): ↑|↑|↑|↑|— contributes 4 unpaired electrons. Total = 1 + 4 = <strong>5 unpaired electrons</strong>.</p>'},
  {id:'p143', difficulty:'hard', type:'multi', tag:'Exceptions', q:'Molybdenum (Mo, Z=42) has the exception configuration [Kr] 5s^1 4d^5 (a half-filled d, analogous to chromium). How many total unpaired electrons does it have?', answer:'6', isText:true, tolerance:0, solution:'<p>5s^1 contributes 1 unpaired electron. 4d^5 (all 5 orbitals singly filled by Hund\'s rule) contributes 5 unpaired electrons. Total = 1 + 5 = <strong>6 unpaired electrons</strong>.</p>'},
  {id:'p144', difficulty:'hard', type:'calc', tag:'Photon Energy', q:'What is the frequency (in Hz) of a photon with an energy of 4.50 × 10^-19 J?', answer:6.79e14, unit:'Hz', tolerance:5e12, solution:'<p>ν = E/h = (4.50×10^-19) ÷ (6.626×10^-34) = <strong>6.79 × 10^14 Hz</strong></p>'},
  {id:'p145', difficulty:'hard', type:'concept', tag:'EM Spectrum', q:'An X-ray photon (very short wavelength) is compared to a microwave photon (long wavelength). Which correctly compares their properties?', choices:['The X-ray photon has higher frequency and higher energy than the microwave photon','The X-ray photon has lower frequency but higher energy','The microwave photon always has more energy since it has a longer wavelength','Frequency and energy are unrelated to wavelength'], correct:0, solution:'<p>Frequency and wavelength are inversely related (ν=c/λ), and energy and frequency are directly related (E=hν). A much shorter wavelength (X-ray) means much higher frequency, and therefore much higher energy per photon, than a long-wavelength microwave.</p>'},
  {id:'p146', difficulty:'hard', type:'multi', tag:'Exceptions', q:'Platinum (Pt, Z=78) has the exception configuration [Xe] 6s^1 4f^14 5d^9. How many total unpaired electrons does it have?', answer:'2', isText:true, tolerance:0, solution:'<p>6s^1 contributes 1 unpaired electron. 5d^9 (5 orbitals: 4 pairs plus 1 single, since 9 = 4×2+1): ↑↓|↑↓|↑↓|↑↓|↑ contributes 1 unpaired electron. Total = 1 + 1 = <strong>2 unpaired electrons</strong>.</p>'},
  {id:'p147', difficulty:'hard', type:'calc', tag:'Photon Energy', q:'What is the wavelength (in nm) of a photon with an energy of 6.00 × 10^-19 J?', answer:331.3, unit:'nm', tolerance:2, solution:'<p>ν = E/h = (6.00×10^-19)÷(6.626×10^-34) = 9.055×10^14 Hz<br>λ = c/ν = (3.00×10^8)÷(9.055×10^14) = <strong>331.3 nm</strong></p>'},
  {id:'p148', difficulty:'hard', type:'multi', tag:'Bohr Transitions', q:'A hydrogen electron absorbs a photon and transitions from n=2 to n=6. Calculate the energy absorbed, in J.', answer:'4.84e-19', isText:true, tolerance:0, solution:'<p>E2 = -5.45×10^-19 J. E6 = -6.06×10^-20 J.<br>ΔE = E6 - E2 = -6.06×10^-20 - (-5.45×10^-19) = <strong>4.84 × 10^-19 J</strong> absorbed.</p>'},
  {id:'p149', difficulty:'hard', type:'concept', tag:'Emission Spectra', q:'Which of the following best explains why the emission spectrum of hydrogen consists of discrete lines rather than a continuous range of colors?', choices:['Electrons can only exist at specific, quantized energy levels, so only specific energy differences (and therefore specific wavelengths) are possible','Hydrogen atoms can only absorb light, not emit it','The human eye can only detect certain wavelengths','Electrons move continuously and randomly emit any wavelength'], correct:0, solution:'<p>Because electron energy levels are quantized (fixed, discrete values), only specific energy gaps — and therefore only specific photon wavelengths — are possible when electrons transition between levels. This produces distinct spectral lines, not a continuous rainbow.</p>'},
  {id:'p150', difficulty:'hard', type:'calc', tag:'Electron Configuration', q:'How many total electrons are in a neutral atom with the configuration [Kr] 5s^2 4d^10 5p^3?', answer:51, unit:'electrons', tolerance:0, solution:'<p>[Kr] = 36 electrons. Adding 5s^2 (+2), 4d^10 (+10), and 5p^3 (+3): 36+2+10+3 = <strong>51 electrons</strong> (this is antimony, Sb).</p>'},
  {id:'p151', difficulty:'hard', type:'multi', tag:'Electron Config', q:'Cadmium (Cd, Z=48) has the configuration [Kr] 5s^2 4d^10. Determine the number of unpaired electrons.', answer:'0', isText:true, tolerance:0, solution:'<p>Both 5s^2 and 4d^10 are completely filled sublevels — every orbital is paired. Cadmium has <strong>0 unpaired electrons</strong>, even though it is technically in the d-block.</p>'},
  {id:'p152', difficulty:'hard', type:'calc', tag:'Photon Energy', q:'What is the energy (in J) of a single X-ray photon with a wavelength of 0.100 nm?', answer:1.99e-15, unit:'J', tolerance:0.02e-15, solution:'<p>ν = c/λ = (3.00×10^8)÷(0.100×10^-9) = 3.00×10^18 Hz<br>E = hν = (6.626×10^-34)(3.00×10^18) = <strong>1.99 × 10^-15 J</strong> — vastly more energetic than a visible-light photon.</p>'},
  {id:'p153', difficulty:'hard', type:'calc', tag:'Bohr Model', q:'What is the minimum energy (in J) needed to ionize a hydrogen electron starting from n = 3?', answer:2.42e-19, unit:'J', tolerance:5e-21, solution:'<p>Ionization energy from level n equals |Eₙ|. |E3| = 2.18×10^-18 ÷ 9 = <strong>2.42 × 10^-19 J</strong>.</p>'},
  {id:'p154', difficulty:'hard', type:'calc', tag:'Valence Electrons', q:'How many valence electrons does bismuth (Bi, Z=83, configuration [Xe] 6s^2 4f^14 5d^10 6p^3) have?', answer:5, unit:'valence electrons', tolerance:0, solution:'<p>Valence electrons are counted from the outermost s and p sublevels only (the filled inner d and f sublevels are not valence): 6s^2 + 6p^3 = <strong>5 valence electrons</strong>.</p>'},
  {id:'p155', difficulty:'hard', type:'concept', tag:'Exceptions', q:'A student claims that because zinc (Zn, Z=30, config [Ar] 4s^2 3d^10) has a completely filled d sublevel, it must be an Aufbau exception like chromium and copper. Evaluate this claim.', choices:['The claim is false — Zn\'s configuration [Ar] 4s^2 3d^10 is exactly what standard Aufbau filling predicts for Z=30; no early electron jump is required, unlike the true exceptions Cr and Cu','The claim is true — Zn is exactly like Cu','The claim is false because Zn does not have a filled d sublevel','The claim is true because all filled d sublevels require an exception'], correct:0, solution:'<p>Zinc\'s configuration follows the Aufbau principle exactly as predicted — no electron needs to shift early from 4s to 3d. It simply happens to reach a filled 3d^10 through normal, sequential filling, unlike Cr and Cu, which truly deviate from the predicted pattern.</p>'},
  {id:'p156', difficulty:'hard', type:'calc', tag:'Wave Equations', q:'What is the frequency (in Hz) of a gamma ray photon with a wavelength of 1.00 × 10^-12 m?', answer:3.00e20, unit:'Hz', tolerance:1e18, solution:'<p>ν = c/λ = (3.00×10^8) ÷ (1.00×10^-12) = <strong>3.00 × 10^20 Hz</strong> — an extremely high frequency, typical of gamma radiation.</p>'},
  {id:'p157', difficulty:'hard', type:'multi', tag:'Unpaired Electrons', q:'Ruthenium (Ru, Z=44) has the exception configuration [Kr] 5s^1 4d^7. Determine its total number of unpaired electrons.', answer:'4', isText:true, tolerance:0, solution:'<p>5s^1 contributes 1 unpaired electron. 4d^7 (5 orbitals: first fill all 5 singly, then pair the remaining 2): ↑↓|↑↓|↑|↑|↑ contributes 3 unpaired electrons. Total = 1 + 3 = <strong>4 unpaired electrons</strong>.</p>'},
  {id:'p158', difficulty:'hard', type:'calc', tag:'Wave Equations', q:'What is the wavelength (in m) of a radio wave with a frequency of 9.50 × 10^7 Hz (a typical FM radio frequency)?', answer:3.16, unit:'m', tolerance:0.05, solution:'<p>λ = c/ν = (3.00×10^8) ÷ (9.50×10^7) = <strong>3.16 m</strong> — radio wavelengths are on the scale of meters, unlike the nanometer scale of visible light.</p>'},
  {id:'p159', difficulty:'hard', type:'multi', tag:'Bohr Model', q:'Rank hydrogen atoms with electrons in n=1, n=2, and n=4 by decreasing ionization energy (energy needed to remove that electron). Give the ionization energy of the n=2 case, in J, as your answer.', answer:'5.45e-19', isText:true, tolerance:0, solution:'<p>Ranking: |E1| = 2.18×10^-18 J (most) > |E2| = 5.45×10^-19 J > |E4| = 1.36×10^-19 J (least). The n=2 ionization energy is <strong>5.45 × 10^-19 J</strong>.</p>'},
  {id:'p160', difficulty:'hard', type:'concept', tag:'Quantum Rules', q:'A ground-state atom has 2 unpaired electrons in its outermost p sublevel, which contains a total of 4 electrons. Which orbital diagram is consistent with this description?', choices:['np^4 (e.g., oxygen\'s 2p^4): ↑↓ | ↑ | ↑','np^2 with both electrons paired in one orbital','np^6, fully filled with no unpaired electrons','np^3, all three orbitals singly filled'], correct:0, solution:'<p>An np^4 configuration, following Hund\'s rule, places one electron in each of the 3 orbitals first, then pairs the 4th: ↑↓ | ↑ | ↑ — giving exactly 4 electrons and 2 unpaired, matching oxygen\'s 2p^4.</p>'},
  {id:'p161', difficulty:'hard', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does a ground-state atom of tellurium (Te, Z=52, configuration [Kr] 5s^2 4d^10 5p^4) have?', answer:2, unit:'unpaired electrons', tolerance:0, solution:'<p>5p^4 follows the same pattern as oxygen\'s 2p^4 (Hund\'s rule): ↑↓ | ↑ | ↑ → <strong>2 unpaired electrons</strong>.</p>'},
  {id:'p162', difficulty:'hard', type:'multi', tag:'Electron Config', q:'An unknown transition metal ion X^2+ has the configuration [Ar] 3d^5, formed by removing the 4s electrons first from neutral X ([Ar] 4s^2 3d^5). Identify element X.', answer:'Manganese', isText:true, tolerance:0, solution:'<p>Neutral X: [Ar] 4s^2 3d^5 → 18+2+5 = 25 electrons. This is <strong>manganese</strong> (Z=25). When forming cations, transition metals lose 4s electrons before 3d electrons, even though 4s filled first in the neutral atom — because once electrons are present, 3d becomes lower in energy than 4s.</p>'},
  {id:'p163', difficulty:'hard', type:'calc', tag:'Orbital Counting', q:'What is the maximum number of electrons in the entire n = 3 energy level (using 3s + 3p + 3d)?', answer:18, unit:'electrons', tolerance:0, solution:'<p>n=3: 3s(2) + 3p(6) + 3d(10) = <strong>18 electrons</strong> — this matches the general formula 2n² for n=3 (2×9=18).</p>'},
  {id:'p164', difficulty:'hard', type:'multi', tag:'Unpaired Electrons', q:'Osmium (Os, Z=76) has the configuration [Xe] 6s^2 4f^14 5d^6. Determine the number of unpaired electrons in just the 5d sublevel.', answer:'4', isText:true, tolerance:0, solution:'<p>5d^6 (Hund\'s rule, 5 orbitals): fill all 5 singly first (5↑), then pair 1: ↑↓|↑|↑|↑|↑ → <strong>4 unpaired electrons</strong> in the 5d sublevel.</p>'},
  {id:'p165', difficulty:'hard', type:'calc', tag:'Bohr Transitions', q:'What is the wavelength (in nm) of a photon emitted when a hydrogen electron falls from n = 5 to n = 3 (a Paschen series, infrared transition)?', answer:1282, unit:'nm', tolerance:10, solution:'<p>E5 = -8.72×10^-20 J. E3 = -2.42×10^-19 J.<br>ΔE = E3 - E5 = -1.55×10^-19 J → magnitude 1.55×10^-19 J<br>λ = hc/E = (6.626×10^-34 × 3.00×10^8) ÷ (1.55×10^-19) = <strong>1282 nm</strong> (infrared, Paschen series)</p>'},
  {id:'p166', difficulty:'hard', type:'multi', tag:'Bohr Model', q:'A photon with energy 1.50 × 10^-18 J strikes a ground-state hydrogen atom (n=1, |E1| = 2.18 × 10^-18 J). Does this photon have enough energy to ionize the atom? If not, calculate how much additional energy (in J) would be needed.', answer:'6.8e-19', isText:true, tolerance:0, solution:'<p>1.50×10^-18 J < 2.18×10^-18 J, so the photon does NOT have enough energy to ionize hydrogen from n=1. The shortfall is 2.18×10^-18 - 1.50×10^-18 = <strong>6.8 × 10^-19 J</strong> more energy needed.</p>'},
  {id:'p167', difficulty:'hard', type:'multi', tag:'Orbital Counting', q:'Compare the maximum number of electrons in the 4f sublevel to the maximum number of electrons in the entire n=1 energy level. Which is greater, and by how many electrons?', answer:'12', isText:true, tolerance:0, solution:'<p>4f sublevel max: 14 electrons. n=1 energy level max: 2 electrons. The 4f sublevel holds more, by 14 - 2 = <strong>12 electrons</strong>.</p>'},
  {id:'p168', difficulty:'hard', type:'calc', tag:'Photon Energy', q:'What is the energy (in J) of a single photon of light with a wavelength of exactly 400. nm, the boundary between visible and UV light?', answer:4.97e-19, unit:'J', tolerance:5e-21, solution:'<p>ν = c/λ = (3.00×10^8)÷(400×10^-9) = 7.50×10^14 Hz<br>E = hν = (6.626×10^-34)(7.50×10^14) = <strong>4.97 × 10^-19 J</strong></p>'},
  {id:'p169', difficulty:'hard', type:'concept', tag:'Bohr Model', q:'Which statement correctly explains why hydrogen\'s Lyman series (transitions to n=1) produces higher-energy photons than its Balmer series (transitions to n=2)?', choices:['Transitions ending at n=1 involve a larger energy level gap than transitions ending at n=2, since n=1 is much lower in energy','The Lyman series involves more electrons than the Balmer series','Lyman series photons travel faster than Balmer series photons','There is no real difference between the two series'], correct:0, solution:'<p>Because n=1 sits at a much lower (more negative) energy than n=2, any transition ending at n=1 spans a larger energy drop than the corresponding transition ending at n=2 — producing higher-energy, shorter-wavelength (UV) photons for the Lyman series versus visible/near-UV for the Balmer series.</p>'},
  {id:'p170', difficulty:'hard', type:'calc', tag:'Unpaired Electrons', q:'How many unpaired electrons does a ground-state atom of tungsten (W, Z=74, configuration [Xe] 6s^2 4f^14 5d^4) have?', answer:4, unit:'unpaired electrons', tolerance:0, solution:'<p>5d^4 (Hund\'s rule, 4 of the 5 orbitals get 1 electron each): ↑|↑|↑|↑|— → <strong>4 unpaired electrons</strong>. The filled 6s^2 and 4f^14 sublevels contribute 0.</p>'},
  {id:'p171', difficulty:'hard', type:'multi', tag:'Photon Energy', q:'Two photons are compared: Photon A has wavelength 200 nm; Photon B has wavelength 800 nm. Calculate the energy of Photon A (in J), and state which photon carries more energy.', answer:'9.94e-19', isText:true, tolerance:0, solution:'<p>E_A = hc/λ = (6.626×10^-34 × 3.00×10^8) ÷ (200×10^-9) = <strong>9.94 × 10^-19 J</strong>. Since energy is inversely proportional to wavelength, the shorter-wavelength Photon A carries more energy than Photon B.</p>'}

];
